import { test, expect } from '@playwright/test';

test.describe('404 Page Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display 404 page when navigating to invalid URL', async ({ page }) => {
    await page.goto('/invalid-page-that-does-not-exist');

    const heading = page.getByRole('heading', { level: 1 });
    await expect(heading).toContainText('404');
  });

  test('should display 404 error message on invalid route', async ({ page }) => {
    await page.goto('/this-route-does-not-exist-12345');

    const errorMessage = page.getByText(/page not found|not found|404/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should have working home link on 404 page', async ({ page }) => {
    await page.goto('/nonexistent-url');

    const homeLink = page.getByRole('link', { name: /home|back to home/i });
    await expect(homeLink).toBeVisible();

    await homeLink.click();
    await expect(page).toHaveURL('/');
  });

  test('should display 404 for deeply nested invalid paths', async ({ page }) => {
    await page.goto('/invalid/nested/path/structure');

    const notFoundElement = page.getByText(/404|not found/i);
    await expect(notFoundElement).toBeVisible();
  });
});
